PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?diagnosis a sphn:BilledDiagnosis ;
               sphn:hasCode ?code .
    ?code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
  MINUS {
    GRAPH ?g { ?administration a sphn:DrugAdministrationEvent . }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (SUM(?without_diagnosis) AS ?patients_without_billed_diagnosis)
       (ROUND(1000.0 * SUM(?without_diagnosis) / COUNT(DISTINCT ?g)) / 10 AS ?pct)
WHERE {
  GRAPH ?g { ?case a sphn:AdministrativeCase . }
  BIND (IF(EXISTS { GRAPH ?g { ?diagnosis a sphn:BilledDiagnosis . } }, 0, 1) AS ?without_diagnosis)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?surgery_patient) AS ?patients_with_surgery)
