PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?country_concept (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?nationality a sphn:Nationality ;
                 sphn:hasAssociatedCountry ?country .
    ?country sphn:hasCode ?country_code .
    ?country_code a ?country_concept .
  }
  FILTER (STRSTARTS(STR(?country_concept), "http://snomed.info/id/"))
}
GROUP BY ?country_concept
ORDER BY DESC(?patients)
LIMIT 5

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT (COUNT(?case) AS ?stays)
       (ROUND(AVG(?days)) AS ?avg_length_of_stay_days)
       (SUM(IF(?days > 30, 1, 0)) AS ?stays_longer_than_30_days)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasAdmission ?admission ;
          sphn:hasDischarge ?discharge .
    ?admission sphn:hasDateTime ?admission_time .
    ?discharge sphn:hasDateTime ?discharge_time .
  }
  FILTER (?discharge_time >= ?admission_time)
  BIND (bif:datediff("day", ?admission_time, ?discharge_time) AS ?days)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients_measured)
       (COUNT(DISTINCT ?high_bmi_patient) AS ?patients_with_bmi_30_or_more)
       (ROUND(1000.0 * COUNT(DISTINCT ?high_bmi_patient) / COUNT(DISTINCT ?g)) / 10 AS ?pct)
WHERE {
  GRAPH ?g {
    ?bmi a sphn:BodyMassIndex ;
         sphn:hasQuantity/sphn:hasValue ?bmi_value .
  }
  BIND (IF(?bmi_value >= 30, ?g, ?no_patient) AS ?high_bmi_patient)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?exposure_type (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?exposure a sphn:TobaccoExposure ;
              sphn:hasTypeCode ?type_code .
    ?type_code a ?exposure_type .
  }
  FILTER (STRSTARTS(STR(?exposure_type), "http://snomed.info/id/"))
}
GROUP BY ?exposure_type
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (SUM(?deceased) AS ?deceased_patients)
       (ROUND(1000.0 * SUM(?deceased) / COUNT(DISTINCT ?g)) / 10 AS ?pct)
WHERE {
  GRAPH ?g { ?case a sphn:AdministrativeCase . }
  BIND (IF(EXISTS { GRAPH ?g { ?death a sphn:Death . } }, 1, 0) AS ?deceased)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX chop: <https://biomedit.ch/rdf/sphn-resource/chop/>

SELECT (COUNT(DISTINCT ?g) AS ?cholera_patients)
       (COUNT(DISTINCT ?ultrasound_patient) AS ?cholera_patients_with_ultrasound)
WHERE {
  GRAPH ?g {
    ?diagnosis a sphn:BilledDiagnosis ;
               sphn:hasCode ?diagnosis_code .
    ?diagnosis_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
  OPTIONAL {
    GRAPH ?g {
      ?procedure a sphn:BilledProcedure ;
                 sphn:hasCode ?procedure_code .
      ?procedure_code a chop:00.0 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?g AS ?ultrasound_patient)
  }
}

DEFINE sql:select-option "order"
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?lab_test rdf:type sphn:LabTest OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    ?lab_test sphn:hasCode ?code .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (GROUP_CONCAT(DISTINCT STR(?coverage_type); separator=", ") AS ?coverage_types)
WHERE {
  GRAPH ?g {
    ?insurance a sphn:InsuranceStatus ;
               sphn:hasCoverageType ?coverage_type .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?icd_concept (SAMPLE(?label) AS ?name) (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?diagnosis a sphn:OncologyDiagnosis ;
               sphn:hasCode ?code .
    ?code a ?icd_concept .
  }
  FILTER (STRSTARTS(STR(?icd_concept), "https://biomedit.ch/rdf/sphn-resource/icd-10-gm/"))
  OPTIONAL {
    GRAPH <https://biomedit.ch/rdf/sphn-resource/global> { ?icd_concept rdfs:label ?label . }
    FILTER (LANGMATCHES(LANG(?label), "de"))
  }
}
GROUP BY ?icd_concept
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?rank (COUNT(?diagnosis) AS ?billed_diagnoses) (COUNT(DISTINCT ?g) AS ?patients)
