  FILTER (STRSTARTS(STR(?rank), "http://snomed.info/id/"))
}
GROUP BY ?rank
ORDER BY DESC(?billed_diagnoses)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?reaction_type (COUNT(?allergy) AS ?allergies) (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?allergy a sphn:Allergy ;
             sphn:hasReactionTypeCode ?reaction_code .
    ?reaction_code a ?reaction_type .
  }
  FILTER (STRSTARTS(STR(?reaction_type), "http://snomed.info/id/"))
}
GROUP BY ?reaction_type
ORDER BY DESC(?allergies)
LIMIT 5

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?provider_category (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasDataProvider ?provider .
    ?provider sphn:hasCategory ?provider_category .
  }
}
GROUP BY ?provider_category
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?hypertension a sphn:Diagnosis ;
                  sphn:hasCode ?hypertension_code .
    ?hypertension_code sphn:hasIdentifier ?hypertension_icd .
    ?diabetes a sphn:Diagnosis ;
              sphn:hasCode ?diabetes_code .
    ?diabetes_code sphn:hasIdentifier ?diabetes_icd .
  }
  FILTER (STRSTARTS(?hypertension_icd, "I10"))
  FILTER (STRSTARTS(?diabetes_icd, "E11"))
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?hypertension a sphn:BilledDiagnosis ;
                  sphn:hasCode ?hypertension_code .
    ?hypertension_code a icd-10-gm:I10 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    ?diabetes a sphn:BilledDiagnosis ;
              sphn:hasCode ?diabetes_code .
    ?diabetes_code a icd-10-gm:E11 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?icd_code (SAMPLE(?code_name) AS ?name) (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?diagnosis a sphn:Diagnosis ;
               sphn:hasCode ?code .
    ?code sphn:hasCodingSystemAndVersion ?coding_system ;
          sphn:hasIdentifier ?icd_code ;
          sphn:hasName ?code_name .
  }
  FILTER (STRSTARTS(?coding_system, "ICD-10-GM"))
}
GROUP BY ?icd_code
ORDER BY DESC(?patients)
LIMIT 10

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ordo: <https://biomedit.ch/rdf/sphn-resource/ordo/>
PREFIX snomed: <http://snomed.info/id/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?diagnosis a sphn:Diagnosis ; sphn:hasCode ?code . ?code a ordo:Orphanet_558 .
    ?sex a sphn:AdministrativeSex ; sphn:hasCode ?sex_code . ?sex_code a snomed:248152002 .
    ?birth_date a sphn:BirthDate ; sphn:hasYear ?year .
  }
  FILTER (?year = 1975)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g { ?case a sphn:AdministrativeCase ; sphn:hasAdmissionDateTime ?admission . }
  FILTER (?admission >= "2024-02-12T14:06:11"^^xsd:dateTime && ?admission < "2024-02-12T14:06:12"^^xsd:dateTime)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (MAX(?admission) AS ?latest)
WHERE { GRAPH ?g { ?case a sphn:AdministrativeCase ; sphn:hasAdmissionDateTime ?admission . } }

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?sex ?year (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?sex_record a sphn:AdministrativeSex ; sphn:hasCode ?sex_code . ?sex_code a ?sex .
    ?birth_date a sphn:BirthDate ; sphn:hasYear ?year .
  }
}
GROUP BY ?sex ?year

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?decade (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g { ?age a sphn:Age ; sphn:hasQuantity/sphn:hasValue ?years . }
  BIND (FLOOR(?years / 10) * 10 AS ?decade)
}
GROUP BY ?decade

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?bmi (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g { ?measurement a sphn:BodyMassIndex ; sphn:hasQuantity/sphn:hasValue ?value . }
  BIND (ROUND(?value) AS ?bmi)
}
GROUP BY ?bmi

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g { ?birth_date a sphn:BirthDate ; sphn:hasYear ?year . }
  FILTER (?year >= 1975 && ?year <= 1975)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g { ?case a sphn:AdministrativeCase ; sphn:hasAdmissionDateTime ?admission . }
  FILTER (SUBSTR(STR(?admission), 1, 7) = "2024-02")
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g { ?case a sphn:AdministrativeCase ; sphn:hasAdmissionDateTime ?admission . }
  FILTER (bif:datediff("year", ?admission, "2026-01-01T00:00:00"^^xsd:dateTime) <= 2)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (AVG(bif:datediff("day", ?admission, ?discharge)) AS ?days)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ; sphn:hasAdmissionDateTime ?admission ; sphn:hasDischargeDateTime ?discharge .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (SUM(?patients) AS ?total)
WHERE {
  {
    SELECT ?class (COUNT(DISTINCT ?g) AS ?patients)
    WHERE { GRAPH ?g { ?diagnosis a sphn:Diagnosis ; sphn:hasCode ?code . ?code a ?class . } }
    GROUP BY ?class
    ORDER BY DESC(?patients)
    LIMIT 10
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(*) AS ?classes)
WHERE {
  {
    SELECT DISTINCT ?class
    WHERE { GRAPH ?g { ?diagnosis a sphn:Diagnosis ; sphn:hasCode ?code . ?code a ?class . } }
    LIMIT 10
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g { ?article a sphn:DrugArticle ; sphn:hasCode ?code . ?code sphn:hasIdentifier ?code_id . }
  FILTER (STRSTARTS(?code_id, "E11"))
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g { ?article a sphn:DrugArticle ; sphn:hasCode ?code . ?code sphn:hasIdentifier ?code_id . }
  FILTER (?code_id = "248153007")
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (AVG(?cases) AS ?mean_cases_per_patient)
WHERE {
  {
    SELECT ?g (COUNT(DISTINCT ?case) AS ?cases)
    WHERE {
      GRAPH ?g {
        ?subject a sphn:SubjectPseudoIdentifier .
        OPTIONAL { ?case a sphn:AdministrativeCase . }
      }
    }
    GROUP BY ?g
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasDischargeDateTime ?discharge .
  }
  FILTER(
    ?discharge >= "2025-01-01T00:00:00Z"^^xsd:dateTime &&
    ?discharge < "2026-01-01T00:00:00Z"^^xsd:dateTime
  )
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (COUNT(DISTINCT ?g) AS ?patients_without_death_record)
WHERE {
  GRAPH ?g { ?subject a sphn:SubjectPseudoIdentifier . }
  FILTER NOT EXISTS {
    GRAPH ?g { ?death a sphn:Death . }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?bmi a sphn:BodyMassIndex ;
         sphn:hasQuantity ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:kgperm2 .
  }
  FILTER(?value >= 30)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?measurement a sphn:BodyTemperatureMeasurement ;
                 sphn:hasResult ?result .
    ?result a sphn:BodyTemperature ;
            sphn:hasQuantity ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:Cel .
  }
  FILTER(?value > 38)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT ?recording_status (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?subject a sphn:SubjectPseudoIdentifier .
    OPTIONAL { ?measurement a sphn:BodyWeightMeasurement . }
  }
  BIND(
    IF(BOUND(?measurement), "weight recorded", "no weight recorded")
    AS ?recording_status
  )
}
GROUP BY ?recording_status

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  { GRAPH ?g { ?measurement a sphn:BodyHeightMeasurement . } }
  UNION
  { GRAPH ?g { ?measurement a sphn:BodyWeightMeasurement . } }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT ?fixation_method (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?sample a sphn:Sample ;
            sphn:hasFixationType ?fixation .
  }
  BIND(STRAFTER(STR(?fixation), "#") AS ?fixation_method)
}
GROUP BY ?fixation_method
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?specimen a sphn:TumorSpecimen ;
              sphn:hasTumorPurity ?purity .
    ?purity sphn:hasValue ?value .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?assay a sphn:SequencingAssay ;
           sphn:hasSequencingRun ?run .
    ?run a sphn:SequencingRun .
  }
  FILTER NOT EXISTS {
    GRAPH ?g { ?run sphn:hasQualityControlMetric ?metric . }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (COUNT(*) AS ?patients)
WHERE {
  {
    SELECT ?g
    WHERE {
      GRAPH ?g {
        ?preparation a sphn:LibraryPreparation ;
                     sphn:hasQualityControlMetric ?metric .
      }
    }
    GROUP BY ?g
    HAVING(COUNT(DISTINCT ?metric) >= 2)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT ?year (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?consent a sphn:Consent ;
             sphn:hasDateTime ?date .
  }
  BIND(YEAR(?date) AS ?year)
}
GROUP BY ?year
ORDER BY ?year

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?directive a sphn:ResuscitationDirective .
    ?exposure a sphn:TobaccoExposure .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g { ?nursing_diagnosis a sphn:NursingDiagnosis . }
  FILTER NOT EXISTS {
    GRAPH ?g { ?billed_diagnosis a sphn:BilledDiagnosis . }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT ?morphology (COUNT(DISTINCT ?g) AS ?patients)
