  GRAPH ?g {
    ?event a sphn:MicrobiologyMicroscopyLabTestEvent ;
           sphn:hasLabTest/sphn:hasResult ?result .
    ?result a sphn:MicrobiologyMicroscopyResult ;
            sphn:hasCellMorphology ?category .
  }
  BIND(STRAFTER(STR(?category), "#") AS ?morphology)
}
GROUP BY ?morphology

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?descriptor a sphn:VariantDescriptor ;
                sphn:hasGeneticVariation ?variation .
    ?variation a sphn:SingleNucleotideVariation .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT ?unit (AVG(?value) AS ?mean_depth) (MAX(?value) AS ?maximum_depth)
WHERE {
  {
    SELECT DISTINCT ?g ?run ?quantity ?unit ?value
    WHERE {
      GRAPH ?g {
        ?assay a sphn:SequencingAssay ;
               sphn:hasSequencingRun ?run .
        ?run sphn:hasMeanReadDepth ?quantity .
        ?quantity sphn:hasValue ?value ;
                  sphn:hasUnit/sphn:hasCode ?unit_code .
        ?unit_code a ?unit .
      }
      FILTER(STRSTARTS(STR(?unit), "https://biomedit.ch/rdf/sphn-resource/ucum/"))
    }
  }
}
GROUP BY ?unit

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?event a sphn:LabTestEvent ;
           sphn:hasDateTime ?performed ;
           sphn:hasReportDateTime ?reported .
  }
  FILTER(?reported < ?performed)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>
SELECT (AVG(?hours) AS ?mean_stay_hours)
WHERE {
  {
    SELECT DISTINCT ?g ?case ?admission ?discharge
    WHERE {
      GRAPH ?g {
        ?case a sphn:AdministrativeCase ;
              sphn:hasAdmissionDateTime ?admission ;
              sphn:hasDischargeDateTime ?discharge .
      }
      FILTER(?discharge >= ?admission)
    }
  }
  BIND(bif:datediff("hour", ?admission, ?discharge) AS ?hours)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
SELECT ?coverage (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?insurance a sphn:InsuranceStatus ;
               sphn:hasCoverageType ?category .
